# - gelman_loadings_k[1-K].png - Loading-specific convergence plots  
# - gelman_[parameter_type].png - Standard parameter group plots
# ==============================================================================

source(file.path(path_scripts,"Plot.Gelman.R"))

# ==============================================================================
# EFFECTIVE SAMPLE SIZE VISUALIZATION
# ==============================================================================
# PURPOSE: Generates comprehensive ESS diagnostic plots with color-coded adequacy 
# indicators and factor-structured organization. These visualizations help identify 
# sampling efficiency patterns and guide decisions about chain length and sampler 
# configuration for future analyses.
#
# WHAT IT DOES:
# - Creates factor-specific ESS plots for factors[k,t] and lambda[i,k] parameters
# - Generates parameter-type plots for variance, intercept, and other components
# - Implements automatic sorting by ESS value to highlight most problematic cases
# - Adds horizontal reference lines at adequacy threshold (400 ESS)
# - Provides comprehensive adequacy rate statistics in plot annotations
#
# EXPECTED OUTPUT:
# - ess_factors_k[1-K].png - Factor-specific ESS diagnostic plots
# - ess_loadings_k[1-K].png - Loading-specific ESS diagnostic plots
# - ess_[parameter_type].png - Parameter group ESS assessments
# ==============================================================================

source(file.path(path_scripts,"Plot.ESS.R"))

# ------------------------------------------------------------------------------
# MODEL COMPARISON WITH WAIC - BEYOND CONVERGENCE TO MODEL SELECTION
# ------------------------------------------------------------------------------
# WAIC (Widely Applicable Information Criterion) provides model comparison capabilities 
# and model adequacy assessment. For DFA models, WAIC helps validate that our complex 
# factor structure appropriately fits the data without overfitting. Consistency 
# across chains indicates robust model selection, while large differences may signal 
# convergence issues that affect model comparison reliability.

cat("\nMODEL SELECTION AND WAIC ANALYSIS\n")  

if (exists("WAIC_all_chains")) {
  cat("OVERALL MODEL WAIC:\n")
  print(WAIC_all_chains)
  cat("\n")
}

if (exists("WAIC_3chains_separate")) {
  cat("INDIVIDUAL CHAIN WAIC VALUES:\n")
  for (i in seq_along(WAIC_3chains_separate)) {
    cat("Chain", i, "WAIC:\n")
    print(WAIC_3chains_separate[[i]])
    cat("\n")
  }
  
  # Check consistency across chains
  waic_values <- sapply(WAIC_3chains_separate, function(x) x$WAIC)
  waic_range <- max(waic_values) - min(waic_values)
  cat("WAIC Consistency Check:\n")
  cat("  • WAIC range across chains:", round(waic_range, 2), "\n")
  if (waic_range > 10) {
    cat("Large WAIC differences between chains - check convergence\n")
  } else {
    cat("  ✓ WAIC values consistent across chains\n")
  }
}

